//! Данные сайта документации. Создан `cargo xtask gen-docs`; руками не править.

/// Код демонстрации.
pub struct DemoDoc {
    pub name: &'static str,
    pub title: &'static str,
    pub code: &'static str,
    pub html: &'static str,
}

/// Параметр компонента: вид (`prop`, `event`, `pt`), имя, тип, значение по умолчанию, описание, обязательность.
pub struct ParamDoc {
    pub kind: &'static str,
    pub name: &'static str,
    pub ty: &'static str,
    pub default: &'static str,
    pub doc: &'static str,
    pub required: bool,
}

/// Компонент крейта.
pub struct CompDoc {
    pub name: &'static str,
    pub params: &'static [ParamDoc],
}

/// Структура Pass Through.
pub struct PtDoc {
    pub name: &'static str,
    pub fields: &'static [(&'static str, &'static str)],
}

/// Страница компонента.
pub struct PageDoc {
    pub name: &'static str,
    pub description: &'static str,
    pub imports: &'static str,
    pub demos: &'static [DemoDoc],
    pub comps: &'static [CompDoc],
    pub pt: &'static [PtDoc],
    pub classes: &'static [&'static str],
    pub notes: &'static str,
    pub a11y: &'static str,
}

